if (typeof schema === 'string') {
  try {
    schema = JSON.parse(schema);
  } catch (e) {
    helpers.error('Invalid JSON schema');
    schema = { type: 'object', properties: {} };
  }
}

return {
  name: node.properties.toolName?.value || 'my_tool',
  description: node.properties.toolDescription?.value || 'Custom tool',
  enabled: node.properties.enabled?.value !== false,
  schema: schema || { type: 'object', properties: {} },
  code: node.properties.code?.value || 'return { success: true };'
};
